            padding: 30px 0;
            border-top: 2px solid #00d4ff;
            margin-top: 50px;
            font-size: 19px;
            color: #90ee90;
        }

        @media (max-width: 768px) {
            h1 {
                font-size: 36px;
            }

            h2 {
                font-size: 26px;
            }

            .diagram-grid {
                grid-template-columns: 1fr;
            }

            .controls {
                flex-direction: column;
            }

            button {
                width: 100%;
