</head>
<body>
    <div class="container">
        <header>
            <h1>LOTTE TOWER</h1>
            <p class="subtitle">Architectural Analysis & 3D Study</p>
            <p class="facts">Height: 555m | Floors: 123 | Location: Seoul, South Korea</p>
        </header>

        <section class="section">
            <h2>3D Model Viewer</h2>
            <p class="info-text">Interactive visualization of Lotte Tower's geometric structure. Use keyboard controls or buttons to navigate the model.</p>

            <div class="keyboard-help">
                <h4>Keyboard Controls</h4>
                <p><span class="key">↑</span> <span class="key">↓</span> <span class="key">←</span> <span class="key">→</span> Rotate model</p>
                <p><span class="key">+</span> / <span class="key">-</span> Zoom in/out</p>
                <p><span class="key">R</span> Reset view | <span class="key">Space</span> Auto-rotate toggle</p>
            </div>

            <div class="controls">
                <button id="rotateUpBtn" aria-label="Rotate up">↑ Rotate Up</button>
                <button id="rotateDownBtn" aria-label="Rotate down">↓ Rotate Down</button>
                <button id="rotateLeftBtn" aria-label="Rotate left">← Rotate Left</button>
                <button id="rotateRightBtn" aria-label="Rotate right">→ Rotate Right</button>
                <button id="zoomInBtn" aria-label="Zoom in">+ Zoom In</button>
                <button id="zoomOutBtn" aria-label="Zoom out">- Zoom Out</button>
                <button id="resetBtn" aria-label="Reset view">Reset View</button>
                <button id="autoRotateBtn" aria-label="Toggle auto-rotation">Auto-Rotate</button>
            </div>

            <div class="canvas-container">
                <canvas id="modelCanvas" width="600" height="500" aria-label="3D model of Lotte Tower"></canvas>
            </div>
        </section>

        <section class="section">
            <h2>Architectural Diagrams</h2>
            <p class="info-text">Four fundamental architectural representations of Lotte Tower's design and spatial organization.</p>

            <div class="assumption-box">
                <h4>⚠ Conceptual Assumptions</h4>
                <p>The following diagrams are based on the verified facts (555m height, 123 floors) combined with architectural modeling assumptions. Typical floor area (~6,000 m²) and structural details are conceptual interpretations for visualization purposes and may differ from actual construction specifications.</p>
            </div>

            <div class="diagram-grid">
                <div class="diagram-card">
                    <h3>Site Plan</h3>
                    <canvas class="diagram-canvas" id="sitePlanCanvas" aria-label="Site plan showing tower footprint and surrounding context"></canvas>
                    <p class="diagram-label">Ground Level Context</p>
                    <p class="diagram-description">Overhead view showing the tower's footprint (approximately 120m × 100m), plaza circulation, and relationship to surrounding urban fabric in Seoul's Songpa district.</p>
                </div>

                <div class="diagram-card">
                    <h3>Typical Floor Plan</h3>
                    <canvas class="diagram-canvas" id="floorPlanCanvas" aria-label="Typical floor plan layout"></canvas>
                    <p class="diagram-label">Conceptual Floor Area: ~6,000 m²</p>
                    <p class="diagram-description">Representative mid-tower floor showing core circulation, office/retail zones, and structural column grid. Actual floor areas vary by level and use type.</p>
                </div>

                <div class="diagram-card">
                    <h3>Elevation</h3>
                    <canvas class="diagram-canvas" id="elevationCanvas" aria-label="Tower elevation showing height and facade articulation"></canvas>
                    <p class="diagram-label">Total Height: 555m | 123 Floors</p>
                    <p class="diagram-description">Front elevation illustrating the tower's vertical massing, setback profile, and facade rhythm. Tapered form reduces wind loads at upper levels.</p>
                </div>

                <div class="diagram-card">
                    <h3>Section</h3>
                    <canvas class="diagram-canvas" id="sectionCanvas" aria-label="Vertical section through tower core"></canvas>
                    <p class="diagram-label">Structural Section</p>
                    <p class="diagram-description">Vertical slice showing core structure, floor-to-floor heights (~4.2m typical), mechanical zones, and spatial distribution from base to spire.</p>
                </div>
            </div>
        </section>

        <section class="section">
            <h2>Design Concept</h2>
            <p class="info-text">Lotte Tower represents contemporary Korean architecture, combining commercial, residential, and cultural functions within a sculptural form. The tapered silhouette references traditional Korean ceramics while optimizing structural efficiency and wind resistance at extreme heights.</p>
        </section>

        <footer>
            <p>Lotte Tower Architectural Study | 3D Model & Diagrams | Educational Visualization</p>
        </footer>
    </div>

    <script>
        // 3D Model State
        let modelState = {
            rotationX: 0.5,
            rotationY: 0.5,
            zoom: 1,
            autoRotate: false
        };

        // Canvas Setup
        const modelCanvas = document.getElementById('modelCanvas');
        const ctx = modelCanvas.getContext('2d');

        // Button Event Listeners
        document.getElementById('rotateUpBtn').addEventListener('click', () => {
            modelState.rotationX -= 0.1;
            drawModel();
        });

        document.getElementById('rotateDownBtn').addEventListener('click', () => {
            modelState.rotationX += 0.1;
            drawModel();
        });

        document.getElementById('rotateLeftBtn').addEventListener('click', () => {
            modelState.rotationY -= 0.1;
            drawModel();
        });

        document.getElementById('rotateRightBtn').addEventListener('click', () => {
            modelState.rotationY += 0.1;
            drawModel();
        });

        document.getElementById('zoomInBtn').addEventListener('click', () => {
            modelState.zoom *= 1.2;
            drawModel();
        });

        document.getElementById('zoomOutBtn').addEventListener('click', () => {
            modelState.zoom /= 1.2;
            drawModel();
        });

        document.getElementById('resetBtn').addEventListener('click', () => {
            modelState = { rotationX: 0.5, rotationY: 0.5, zoom: 1, autoRotate: false };
            drawModel();
        });

        document.getElementById('autoRotateBtn').addEventListener('click', () => {
            modelState.autoRotate = !modelState.autoRotate;
            if (modelState.autoRotate) animate();
        });

        // Keyboard Controls
        document.addEventListener('keydown', (e) => {
            switch(e.key) {
                case 'ArrowUp':
                    modelState.rotationX -= 0.1;
                    drawModel();
                    break;
                case 'ArrowDown':
                    modelState.rotationX += 0.1;
                    drawModel();
                    break;
                case 'ArrowLeft':
                    modelState.rotationY -= 0.1;
                    drawModel();
                    break;
                case 'ArrowRight':
                    modelState.rotationY += 0.1;
                    drawModel();
                    break;
                case '+':
                case '=':
                    modelState.zoom *= 1.2;
                    drawModel();
                    break;
                case '-':
                    modelState.zoom /= 1.2;
                    drawModel();
                    break;
                case 'r':
                case 'R':
                    modelState = { rotationX: 0.5, rotationY: 0.5, zoom: 1, autoRotate: false };
                    drawModel();
                    break;
                case ' ':
                    e.preventDefault();
                    modelState.autoRotate = !modelState.autoRotate;
                    if (modelState.autoRotate) animate();
                    break;
            }
        });

        function drawModel() {
            ctx.fillStyle = '#0a0a14';
            ctx.fillRect(0, 0, modelCanvas.width, modelCanvas.height);

            ctx.save();
            ctx.translate(modelCanvas.width / 2, modelCanvas.height / 2);
            ctx.scale(modelState.zoom, modelState.zoom);

            // Draw tower structure
            drawTower();

            ctx.restore();

            // Draw info text
            ctx.fillStyle = '#00d4ff';
            ctx.font = 'bold 19px Arial';
            ctx.fillText('Rotation: ' + modelState.rotationX.toFixed(2) + ', ' + modelState.rotationY.toFixed(2), 20, 30);
            ctx.fillText('Zoom: ' + modelState.zoom.toFixed(2) + 'x', 20, 60);
        }

        function drawTower() {
            const baseWidth = 80;
            const baseHeight = 200;
            const taper = 0.6;

            ctx.strokeStyle = '#00d4ff';
            ctx.fillStyle = 'rgba(0, 212, 255, 0.1)';
            ctx.lineWidth = 2;

            // Apply rotation
            ctx.rotate(modelState.rotationY);
            ctx.rotateX = modelState.rotationX;

            // Draw tapered tower
            ctx.beginPath();
            ctx.moveTo(-baseWidth / 2, baseHeight / 2);
            ctx.lineTo(baseWidth / 2, baseHeight / 2);
            ctx.lineTo(baseWidth / 2 * taper, -baseHeight / 2);
            ctx.lineTo(-baseWidth / 2 * taper, -baseHeight / 2);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // Draw spire
            ctx.beginPath();
            ctx.moveTo(-baseWidth / 2 * taper, -baseHeight / 2);
            ctx.lineTo(0, -baseHeight / 2 - 60);
            ctx.lineTo(baseWidth / 2 * taper, -baseHeight / 2);
            ctx.stroke();

            // Draw floor lines
            ctx.strokeStyle = 'rgba(0, 212, 255, 0.3)';
            ctx.lineWidth = 1;
            for (let i = 0; i < 12; i++) {
                const y = -baseHeight / 2 + (i * baseHeight / 12);
                const w = baseWidth / 2 - (i * baseWidth / 24);
                ctx.beginPath();
                ctx.moveTo(-w, y);
                ctx.lineTo(w, y);
                ctx.stroke();
            }
        }

        function animate() {
            if (modelState.autoRotate) {
                modelState.rotationY += 0.02;
                drawModel();
                requestAnimationFrame(animate);
            }
        }

        // Draw Diagrams
        function drawSitePlan() {
            const canvas = document.getElementById('sitePlanCanvas');
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = '#0a0a14';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Tower footprint
            ctx.fillStyle = 'rgba(0, 212, 255, 0.3)';
            ctx.strokeStyle = '#00d4ff';
            ctx.lineWidth = 3;
            ctx.fillRect(canvas.width / 2 - 50, canvas.height / 2 - 60, 100, 120);
            ctx.strokeRect(canvas.width / 2 - 50, canvas.height / 2 - 60, 100, 120);

            // Plaza
            ctx.strokeStyle = 'rgba(0, 212, 255, 0.5)';
            ctx.lineWidth = 1;
            ctx.strokeRect(canvas.width / 2 - 100, canvas.height / 2 - 110, 200, 220);

            // Grid
            ctx.strokeStyle = 'rgba(0, 212, 255, 0.2)';
            for (let i = 0; i < 5; i++) {
                ctx.beginPath();
                ctx.moveTo(canvas.width / 2 - 100 + i * 50, canvas.height / 2 - 110);
                ctx.lineTo(canvas.width / 2 - 100 + i * 50, canvas.height / 2 + 110);
                ctx.stroke();
            }

            // Label
            ctx.fillStyle = '#90ee90';
            ctx.font = 'bold 19px Arial';
            ctx.fillText('N', canvas.width / 2 + 70, canvas.height / 2 - 100);
        }

        function drawFloorPlan() {
            const canvas = document.getElementById('floorPlanCanvas');
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = '#0a0a14';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Core
            ctx.fillStyle = 'rgba(255, 165, 0, 0.4)';
            ctx.strokeStyle = '#ffa500';
            ctx.lineWidth = 2;
            ctx.fillRect(canvas.width / 2 - 25, canvas.height / 2 - 35, 50, 70);
            ctx.strokeRect(canvas.width / 2 - 25, canvas.height / 2 - 35, 50, 70);

            // Perimeter
            ctx.strokeStyle = '#00d4ff';
            ctx.lineWidth = 2;
            ctx.strokeRect(canvas.width / 2 - 80, canvas.height / 2 - 80, 160, 160);

            // Column grid
            ctx.strokeStyle = 'rgba(0, 212, 255, 0.3)';
            ctx.lineWidth = 1;
            for (let i = 0; i < 4; i++) {
                for (let j = 0; j < 4; j++) {
                    ctx.beginPath();
                    ctx.arc(canvas.width / 2 - 60 + i * 40, canvas.height / 2 - 60 + j * 40, 3, 0, Math.PI * 2);
                    ctx.stroke();
                }
            }

            // Label
            ctx.fillStyle = '#90ee90';
            ctx.font = 'bold 19px Arial';
            ctx.fillText('Core', canvas.width / 2 - 15, canvas.height / 2 + 5);
        }

        function drawElevation() {
            const canvas = document.getElementById('elevationCanvas');
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = '#0a0a14';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Tower profile
            ctx.fillStyle = 'rgba(0, 212, 255, 0.2)';
            ctx.strokeStyle = '#00d4ff';
            ctx.lineWidth = 3;
            ctx.beginPath();
            ctx.moveTo(canvas.width / 2 - 40, canvas.height - 40);
            ctx.lineTo(canvas.width / 2 + 40, canvas.height - 40);
            ctx.lineTo(canvas.width / 2 + 25, 40);
            ctx.lineTo(canvas.width / 2, 20);
            ctx.lineTo(canvas.width / 2 - 25, 40);
            ctx.closePath();
            ctx.fill();
            ctx.stroke();

            // Floor lines
            ctx.strokeStyle = 'rgba(0, 212, 255, 0.4)';
            ctx.lineWidth = 1;
            for (let i = 0; i < 12; i++) {
                const y = canvas.height - 40 - (i * (canvas.height - 80) / 12);
                const offset = i * 2;
                ctx.beginPath();
                ctx.moveTo(canvas.width / 2 - 40 + offset, y);
                ctx.lineTo(canvas.width / 2 + 40 - offset, y);
                ctx.stroke();
            }

            // Label
            ctx.fillStyle = '#90ee90';
            ctx.font = 'bold 19px Arial';
            ctx.fillText('555m', canvas.width / 2 + 50, canvas.height / 2);
        }

        function drawSection() {
            const canvas = document.getElementById('sectionCanvas');
            const ctx = canvas.getContext('2d');
            ctx.fillStyle = '#0a0a14';
            ctx.fillRect(0, 0, canvas.width, canvas.height);

            // Core structure
            ctx.fillStyle = 'rgba(255, 165, 0, 0.3)';
            ctx.strokeStyle = '#ffa500';
            ctx.lineWidth = 2;
            ctx.fillRect(canvas.width / 2 - 20, 30, 40, canvas.height - 60);
            ctx.strokeRect(canvas.width / 2 - 20, 30, 40, canvas.height - 60);

            // Floors
            ctx.strokeStyle = 'rgba(0, 212, 255, 0.4)';
            ctx.lineWidth = 1;
            for (let i = 0; i < 12; i++) {
                const y = 30 + (i * (canvas.height - 60) / 12);
                ctx.beginPath();
                ctx.moveTo(canvas.width / 2 - 50, y);
                ctx.lineTo(canvas.width / 2 + 50, y);
                ctx.stroke();
            }

            // Perimeter
            ctx.strokeStyle = '#00d4ff';
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(canvas.width / 2 - 50, 30);
            ctx.lineTo(canvas.width / 2 + 50, 30);
            ctx.lineTo(canvas.width / 2 + 40, canvas.height - 30);
            ctx.lineTo(canvas.width / 2 - 40, canvas.height - 30);
            ctx.closePath();
            ctx.stroke();

            // Label
            ctx.fillStyle = '#90ee90';
            ctx.font = 'bold 19px Arial';
            ctx.fillText('123 Floors', canvas.width / 2 - 50, canvas.height - 10);
        }

        // Initialize
        drawModel();
        drawSitePlan();
        drawFloorPlan();
        drawElevation();
        drawSection();
    </script>
</body>
</html>
